export const getDosId = (mondayId) => DOS_IDS[String(mondayId)] || null;
export const getAffId = (mondayId) => AFF_IDS[String(mondayId)] || null;
export const getInternalId = (mondayId) => getAffId(mondayId) || getDosId(mondayId) || null;
export const getNextDosNum = () => {
  const yr = new Date().getFullYear();
  const used = Object.values(DOS_IDS).filter(v=>v.startsWith('DOS-'+yr));
  const maxN = used.reduce((m,v)=>Math.max(m,parseInt(v.split('-')[2]||0)),0);
  return 'DOS-'+yr+'-'+String(maxN+1).padStart(4,'0');
};

